-- GenDB engine variant Q15-wrapped_tables: template q15.sql, kind wrapped_tables (generated by generate.py; frozen)
WITH revenue0 AS (
  SELECT
    l_suppkey AS supplier_no,
    SUM(l_extendedprice * (
      1 - l_discount
    )) AS total_revenue
  FROM (
    SELECT
      *
    FROM lineitem
  ) AS lineitem
  WHERE
    l_shipdate >= $1 AND l_shipdate < $1 + INTERVAL '3 MONTH'
  GROUP BY
    l_suppkey
)
SELECT
  s_suppkey,
  s_name,
  s_address,
  s_phone,
  total_revenue
FROM (
  SELECT
    *
  FROM supplier
) AS supplier, revenue0
WHERE
  s_suppkey = supplier_no
  AND total_revenue = (
    SELECT
      MAX(total_revenue)
    FROM revenue0
  )
ORDER BY
  s_suppkey
